/**
 * Writes the WebAuthn vectors from the committed throwaway keys.
 *
 *   node test/fixtures/webauthn/make.ts        (from packages/record)
 *
 * THE KEYS ARE MADE ONLY IF `keys.json` IS MISSING, so running this again re-signs the same credentials. ECDSA
 * signatures are randomised, so the ES256 bytes change on every run, and that is why the vectors are committed
 * rather than regenerated by the tests: a test that signs its own input proves less than one that reads what was
 * written down. The tests that need a fresh challenge sign live, with the same keys, through `authenticator.ts`.
 *
 * The origin is an `.example` host and the person id is not a ULID, as a fixture's must be (`12 §8`).
 */

import { writeFileSync } from 'node:fs';

import { b64url } from '../../../src/webauthn.ts';
import { KEYS_URL, asJSON, assert, register, testKeys, type CborIn, type TestKey } from './authenticator.ts';

const ORIGIN = 'https://studio.example';
const RP_ID = 'studio.example';
const PERSON = 'p_fixture_person';

async function makeKeys(): Promise<{ es256: TestKey; rs256: TestKey }> {
  const es = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
  const rs = await crypto.subtle.generateKey(
    { name: 'RSASSA-PKCS1-v1_5', modulusLength: 2048, publicExponent: new Uint8Array([1, 0, 1]), hash: 'SHA-256' },
    true,
    ['sign', 'verify'],
  );
  const id = () => b64url(crypto.getRandomValues(new Uint8Array(32)));
  return {
    es256: { alg: -7, id: id(), jwk: (await crypto.subtle.exportKey('jwk', es.privateKey)) as Record<string, unknown> },
    rs256: { alg: -257, id: id(), jwk: (await crypto.subtle.exportKey('jwk', rs.privateKey)) as Record<string, unknown> },
  };
}

const keys = testKeys() ?? (await makeKeys());
const kept = { note: 'Throwaway test keys for the WebAuthn vectors. They open nothing.', es256: keys.es256, rs256: keys.rs256 };
writeFileSync(KEYS_URL, `${JSON.stringify(kept, null, 2)}\n`);

const vectors: Record<string, unknown> = { origin: ORIGIN, rpId: RP_ID, person: PERSON };
for (const [name, key] of [['es256', keys.es256], ['rs256', keys.rs256]] as const) {
  const challenge = b64url(crypto.getRandomValues(new Uint8Array(32)));
  const made = await register(key, { rpId: RP_ID, origin: ORIGIN, challenge });
  /* `packed` with a statement that is garbage: registered anyway, because the statement is never read. */
  const packed = await register(key, {
    rpId: RP_ID,
    origin: ORIGIN,
    challenge,
    fmt: 'packed',
    attStmt: new Map<string, CborIn>([['alg', -7], ['sig', new Uint8Array([1, 2, 3])], ['x5c', [new Uint8Array([9, 9, 9])]]]),
  });
  const assertChallenge = b64url(crypto.getRandomValues(new Uint8Array(32)));
  /* ES256 counts and RS256 does not, so the vectors cover both halves of the sign-count rule. */
  const signCount = name === 'es256' ? 7 : 0;
  const asserted = await assert(key, { rpId: RP_ID, origin: ORIGIN, challenge: assertChallenge, signCount, person: PERSON });
  vectors[name] = {
    registration: { challenge, ...asJSON.registration(made) },
    packed: { challenge, ...asJSON.registration(packed) },
    assertion: { challenge: assertChallenge, signCount, ...asJSON.assertion(asserted) },
  };
}

writeFileSync(new URL('./vectors.json', import.meta.url), `${JSON.stringify(vectors, null, 2)}\n`);
console.log('wrote the WebAuthn vectors and kept the test keys');
